package com.estradaplay.comunista;
import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import java.util.*;
/** One-tap road favorites grouped by purpose. */
public final class RoadFavoritesActivity extends ComponentActivity{private LinearLayout page;private final int BG=Color.rgb(9,5,7),SURFACE=Color.rgb(20,10,13),BORDER=Color.rgb(76,38,44),TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38),GOLD=Color.rgb(226,185,76),GREEN=Color.rgb(72,212,134);@Override protected void onCreate(Bundle b){super.onCreate(b);build();}
 private void build(){ScrollView sv=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(18),dp(18),dp(18),dp(28));page.setBackgroundColor(BG);sv.addView(page);setContentView(UnifiedAppShell.wrap(this,"trip",sv));page.addView(t("FAVORITOS DA ESTRADA",27,TEXT,true));page.addView(t("Casa, trabalho, postos, comida, paradas e rotas frequentes. Um toque inicia a navegação.",12,MUTED,false));ArrayList<FavoriteRoadStore.Item>a=FavoriteRoadStore.list(this);renderSpecial(a,FavoriteRoadStore.TYPE_HOME,"CASA");renderSpecial(a,FavoriteRoadStore.TYPE_WORK,"TRABALHO");if(a.isEmpty())page.addView(t("Nenhum favorito ainda. Salve locais pela tela Serviços na Estrada.",14,MUTED,false));for(FavoriteRoadStore.Item x:a){if(FavoriteRoadStore.TYPE_HOME.equals(x.type)||FavoriteRoadStore.TYPE_WORK.equals(x.type))continue;addItem(x);} }
 private void renderSpecial(ArrayList<FavoriteRoadStore.Item>a,String type,String title){FavoriteRoadStore.Item found=null;for(FavoriteRoadStore.Item x:a)if(type.equals(x.type)){found=x;break;}TextView h=t(title,9,type.equals(FavoriteRoadStore.TYPE_HOME)?GREEN:GOLD,true);h.setLetterSpacing(.10f);page.addView(h);LinearLayout.LayoutParams hp=(LinearLayout.LayoutParams)h.getLayoutParams();hp.setMargins(0,dp(16),0,dp(6));h.setLayoutParams(hp);if(found!=null)addItem(found);else page.addView(t("Ainda não definido.",11,MUTED,false));}
 private void addItem(FavoriteRoadStore.Item x){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(8),dp(7),dp(8),dp(7));r.setBackground(panel(SURFACE,13,BORDER));Button go=new Button(this);go.setAllCaps(false);go.setText(x.categoryLabel()+" · "+x.name+"\nINICIAR NAVEGAÇÃO");go.setTextColor(TEXT);go.setTextSize(11);go.setBackgroundColor(Color.TRANSPARENT);go.setOnClickListener(v->{FavoriteRoadStore.touch(this,x);DestinationStore.save(this,new DestinationStore.Destination(x.name,x.lat,x.lon));new OfflineJourneyStore(this).rememberDestination(x.name,x.lat,x.lon);startActivity(new Intent(this,RoadMapActivity.class));});Button del=new Button(this);del.setAllCaps(false);del.setText("REMOVER");del.setTextColor(TEXT);del.setTextSize(9);del.setBackground(panel(Color.rgb(38,18,22),11,BORDER));del.setOnClickListener(v->{FavoriteRoadStore.remove(this,x.lat,x.lon);build();});r.addView(go,new LinearLayout.LayoutParams(0,dp(66),1));r.addView(del,new LinearLayout.LayoutParams(dp(105),dp(58)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.setMargins(0,0,0,dp(7));page.addView(r,rp);}
 private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private GradientDrawable panel(int c,int r,int st){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));if(st!=0)g.setStroke(dp(1),st);return g;}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}}
